import {test,expect} from '@playwright/test'
type ReceiptWindow=Window&{nativeCoachAlertFixture:{writes:boolean[];receive:(owner?:string,kind?:string)=>void};chatUnreadFixture:{total:number;reads:number};coachUnreadFixture:{reads:unknown[]};navigationFixture:{requests:number}}
for(const width of [320,390])test('phone chat notification control preserves the separate Coach choice at '+width+'px',async({page},info)=>{
 await page.routeWebSocket('**/*',ws=>ws.close());await page.setViewportSize({width,height:844});await page.goto('http://127.0.0.1:4283/?coachAlerts=1&large=1');await page.locator('.app-navigation [data-screen="teams"]').click()
 await expect(page.getByRole('button',{name:'Turn off chat notifications',exact:true})).toBeEnabled();await page.getByRole('button',{name:'Turn on Coach alerts',exact:true}).click();await expect(page.getByRole('button',{name:'Turn off Coach alerts',exact:true})).toBeEnabled()
 await page.getByRole('button',{name:'Turn off chat notifications',exact:true}).click();await expect(page.getByText('Chat notifications are off on this iPhone. Your Coach alert choice stays saved.',{exact:true})).toBeVisible();await expect(page.getByRole('button',{name:'Enable chat notifications',exact:true})).toBeEnabled();await expect(page.getByRole('button',{name:'Turn off Coach alerts',exact:true})).toBeEnabled()
 expect(await page.evaluate(()=>(window as unknown as ReceiptWindow).nativeCoachAlertFixture.writes)).toEqual([true]);await page.waitForTimeout(500)
 const reads=await page.evaluate(()=>(window as unknown as ReceiptWindow).chatUnreadFixture.reads);await page.evaluate(()=>{const w=window as unknown as ReceiptWindow;w.chatUnreadFixture.total=11;w.nativeCoachAlertFixture.receive()});await page.waitForTimeout(500);expect(await page.evaluate(()=>(window as unknown as ReceiptWindow).chatUnreadFixture.reads)).toBe(reads)
 await page.getByRole('button',{name:'Enable chat notifications',exact:true}).click();await expect(page.getByRole('button',{name:'Turn off chat notifications',exact:true})).toBeEnabled();expect(await page.evaluate(()=>(window as unknown as ReceiptWindow).nativeCoachAlertFixture.writes)).toEqual([true]);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('chat-receipts-settings-'+width+'.png')})
})
test('a foreground Coach receipt updates counts and preserves an open message draft',async({page},info)=>{
 await page.routeWebSocket('**/*',ws=>ws.close());await page.setViewportSize({width:320,height:844});await page.goto('http://127.0.0.1:4283/?coachAlerts=1&coldCoach=1&large=1')
 const dialog=page.getByRole('dialog',{name:'Coach messages',exact:true}),draft=dialog.locator('[name="body"]');await expect(dialog).toContainText('Bring your return notes');await draft.fill('Keep my serve practice notes.');await page.waitForTimeout(500)
 const baseline=await page.evaluate(()=>{const w=window as unknown as ReceiptWindow;return {counts:w.chatUnreadFixture.reads,tools:w.navigationFixture.requests,readWrites:w.coachUnreadFixture.reads.length}})
 await page.evaluate(()=>{const w=window as unknown as ReceiptWindow;w.chatUnreadFixture.total=11;for(let i=0;i<30;i++)w.nativeCoachAlertFixture.receive()})
 await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-label','Chats, 11 unread messages');await expect(draft).toHaveValue('Keep my serve practice notes.');await expect(draft).toBeFocused();await expect(dialog.locator('[data-connection]')).toHaveValue('99999999-9999-4999-8999-999999999991')
 const after=await page.evaluate(()=>{const w=window as unknown as ReceiptWindow;return {counts:w.chatUnreadFixture.reads,tools:w.navigationFixture.requests,readWrites:w.coachUnreadFixture.reads.length}});expect(after).toEqual({...baseline,counts:baseline.counts+1});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:info.outputPath('chat-receipts-draft.png')})
})
test('foreign and malformed receipts leave an open account form intact and only owned receipts refresh',async({page})=>{
 await page.routeWebSocket('**/*',ws=>ws.close());await page.goto('http://127.0.0.1:4283/?coachAlerts=1');await page.locator('.app-navigation [data-screen="teams"]').click();await expect(page.getByRole('button',{name:'Turn off chat notifications',exact:true})).toBeEnabled();await page.locator('.native-account-entry').click();const account=page.getByRole('dialog',{name:'Account settings'});await expect(account).toBeVisible();await page.waitForTimeout(500)
 const reads=await page.evaluate(()=>(window as unknown as ReceiptWindow).chatUnreadFixture.reads);await page.evaluate(()=>{const w=window as unknown as ReceiptWindow;w.chatUnreadFixture.total=15;w.nativeCoachAlertFixture.receive('foreign');w.nativeCoachAlertFixture.receive(undefined,'invalid')});await page.waitForTimeout(500);expect(await page.evaluate(()=>(window as unknown as ReceiptWindow).chatUnreadFixture.reads)).toBe(reads);await expect(account).toBeVisible();await expect(page.getByRole('complementary',{name:'Coach message alert'})).toBeHidden()
 await page.evaluate(()=>(window as unknown as ReceiptWindow).nativeCoachAlertFixture.receive(undefined,'team'));await expect(page.locator('.app-navigation [data-screen="teams"]')).toHaveAttribute('aria-label','Chats, 15 unread messages');await expect(account).toBeVisible();expect(await page.evaluate(()=>(window as unknown as ReceiptWindow).chatUnreadFixture.reads)).toBe(reads+1)
})
